CREATE OR REPLACE FUNCTION public.ohc_save_compatibility_decision(p_request_id uuid, p_status text, p_admin_notes text, p_reviewed_by text, p_save_rule boolean, p_year_from integer, p_year_to integer, p_replace_conflicts boolean, p_product_sku text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_request public.compatibility_requests%rowtype;
  v_product_sku text;
  v_product_name text;
  v_product_key text;
  v_brand_key text;
  v_model_key text;
  v_generation_key text;
  v_version_key text;
  v_year_from integer;
  v_year_to integer;
  v_conflict_ids uuid[] := array[]::uuid[];
  v_same_status_ids uuid[] := array[]::uuid[];
  v_rule_id uuid;
  v_merged_from integer;
  v_merged_to integer;
begin
  if p_status not in ('analise_necessaria', 'compativel', 'incompativel') then
    return jsonb_build_object('ok', false, 'error', 'invalid_status');
  end if;

  select * into v_request
  from public.compatibility_requests
  where id = p_request_id
  for update;

  if not found then
    return jsonb_build_object('ok', false, 'error', 'request_not_found');
  end if;

  if p_status = 'analise_necessaria' or not coalesce(p_save_rule, false) then
    update public.compatibility_requests
    set
      status = p_status,
      admin_notes = nullif(trim(p_admin_notes), ''),
      reviewed_by = nullif(trim(p_reviewed_by), ''),
      reviewed_at = case when p_status = 'analise_necessaria' then null else now() end,
      matched_rule_id = null,
      decision_source = 'manual_review',
      conflict_detected = false,
      updated_at = now()
    where id = p_request_id;

    return jsonb_build_object('ok', true, 'rule_saved', false, 'status', p_status);
  end if;

  select product.sku, product.nome_produto
  into v_product_sku, v_product_name
  from public.catalog_products as product
  where product.ativo
    and lower(trim(product.sku)) = lower(trim(coalesce(
      nullif(p_product_sku, ''),
      v_request.requested_product_sku
    )))
  limit 1;

  if v_product_sku is null then
    return jsonb_build_object('ok', false, 'error', 'product_not_found');
  end if;

  v_year_from := coalesce(p_year_from, v_request.vehicle_year);
  v_year_to := coalesce(p_year_to, v_request.vehicle_year);

  if v_year_from < 1950 or v_year_to > 2100 or v_year_from > v_year_to then
    return jsonb_build_object('ok', false, 'error', 'invalid_year_range');
  end if;

  v_product_key := public.ohc_normalize_compatibility_text(v_product_sku);
  v_brand_key := public.ohc_normalize_compatibility_text(v_request.vehicle_brand);
  v_model_key := public.ohc_normalize_vehicle_model(v_request.vehicle_brand, v_request.vehicle_model);
  v_generation_key := public.ohc_normalize_compatibility_text(v_request.generation_chassis);
  v_version_key := public.ohc_normalize_compatibility_text(v_request.vehicle_version);

  select coalesce(array_agg(rule.id order by rule.created_at), array[]::uuid[])
  into v_conflict_ids
  from public.compatibility_rules as rule
  where rule.active
    and rule.product_sku_key = v_product_key
    and rule.vehicle_brand_key = v_brand_key
    and rule.vehicle_model_key = v_model_key
    and rule.generation_key = v_generation_key
    and rule.version_key = v_version_key
    and rule.status <> p_status
    and rule.year_from <= v_year_to
    and rule.year_to >= v_year_from;

  if cardinality(v_conflict_ids) > 0 and not coalesce(p_replace_conflicts, false) then
    return jsonb_build_object(
      'ok', false,
      'conflict', true,
      'error', 'conflicting_rule_exists',
      'conflict_count', cardinality(v_conflict_ids)
    );
  end if;

  if cardinality(v_conflict_ids) > 0 then
    insert into public.compatibility_rule_audit (
      rule_id, request_id, action, previous_status, new_status, actor, details
    )
    select
      rule.id, p_request_id, 'conflict_replaced', rule.status, p_status,
      nullif(trim(p_reviewed_by), ''),
      jsonb_build_object('replacement_year_from', v_year_from, 'replacement_year_to', v_year_to)
    from public.compatibility_rules as rule
    where rule.id = any(v_conflict_ids);

    update public.compatibility_rules
    set active = false, updated_at = now()
    where id = any(v_conflict_ids);
  end if;

  select
    coalesce(array_agg(rule.id order by rule.created_at), array[]::uuid[]),
    least(v_year_from, coalesce(min(rule.year_from), v_year_from)),
    greatest(v_year_to, coalesce(max(rule.year_to), v_year_to))
  into v_same_status_ids, v_merged_from, v_merged_to
  from public.compatibility_rules as rule
  where rule.active
    and rule.product_sku_key = v_product_key
    and rule.vehicle_brand_key = v_brand_key
    and rule.vehicle_model_key = v_model_key
    and rule.generation_key = v_generation_key
    and rule.version_key = v_version_key
    and rule.status = p_status
    and rule.year_from <= v_year_to + 1
    and rule.year_to + 1 >= v_year_from;

  if cardinality(v_same_status_ids) > 0 then
    insert into public.compatibility_rule_audit (
      rule_id, request_id, action, previous_status, new_status, actor, details
    )
    select
      rule.id, p_request_id, 'merged', rule.status, p_status,
      nullif(trim(p_reviewed_by), ''),
      jsonb_build_object('merged_year_from', v_merged_from, 'merged_year_to', v_merged_to)
    from public.compatibility_rules as rule
    where rule.id = any(v_same_status_ids);

    update public.compatibility_rules
    set active = false, updated_at = now()
    where id = any(v_same_status_ids);
  end if;

  insert into public.compatibility_rules (
    product_sku, product_sku_key, vehicle_brand, vehicle_brand_key,
    vehicle_model, vehicle_model_key, generation_chassis, generation_key,
    vehicle_version, version_key, year_from, year_to, status, admin_notes,
    evidence_request_id, reviewed_by
  ) values (
    v_product_sku, v_product_key, v_request.vehicle_brand, v_brand_key,
    v_request.vehicle_model, v_model_key,
    nullif(trim(v_request.generation_chassis), ''), v_generation_key,
    nullif(trim(v_request.vehicle_version), ''), v_version_key,
    v_merged_from, v_merged_to, p_status, nullif(trim(p_admin_notes), ''),
    p_request_id, nullif(trim(p_reviewed_by), '')
  ) returning id into v_rule_id;

  insert into public.compatibility_rule_audit (
    rule_id, request_id, action, new_status, actor, details
  ) values (
    v_rule_id, p_request_id, 'created', p_status,
    nullif(trim(p_reviewed_by), ''),
    jsonb_build_object(
      'year_from', v_merged_from,
      'year_to', v_merged_to,
      'replaced_conflicts', cardinality(v_conflict_ids),
      'merged_rules', cardinality(v_same_status_ids)
    )
  );

  update public.compatibility_requests
  set
    status = p_status,
    requested_product_sku = v_product_sku,
    requested_product_name = v_product_name,
    recommended_product_skus = case
      when p_status = 'compativel' and not (v_product_sku = any(recommended_product_skus))
        then array_append(recommended_product_skus, v_product_sku)
      when p_status = 'incompativel'
        then array_remove(recommended_product_skus, v_product_sku)
      else recommended_product_skus
    end,
    admin_notes = nullif(trim(p_admin_notes), ''),
    reviewed_by = nullif(trim(p_reviewed_by), ''),
    reviewed_at = now(),
    matched_rule_id = v_rule_id,
    decision_source = 'manual_review',
    conflict_detected = false,
    updated_at = now()
  where id = p_request_id;

  return jsonb_build_object(
    'ok', true,
    'rule_saved', true,
    'rule_id', v_rule_id,
    'product_sku', v_product_sku,
    'status', p_status,
    'year_from', v_merged_from,
    'year_to', v_merged_to,
    'replaced_conflicts', cardinality(v_conflict_ids),
    'merged_rules', cardinality(v_same_status_ids)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.ohc_normalize_vehicle_model_v2(p_vehicle_brand text, p_vehicle_model text, p_vehicle_year integer DEFAULT NULL::integer, p_vehicle_generation text DEFAULT NULL::text, p_chassis_platform text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO ''
AS $function$
declare
  v_brand_key text := public.ohc_normalize_vehicle_brand(p_vehicle_brand);
  v_raw_brand_key text := public.ohc_normalize_compatibility_text(p_vehicle_brand);
  v_model_key text := public.ohc_normalize_compatibility_text(p_vehicle_model);
  v_without_series text;
begin
  v_model_key := public.ohc_remove_normalized_vehicle_token(v_model_key, v_raw_brand_key);
  v_model_key := public.ohc_remove_normalized_vehicle_token(v_model_key, v_brand_key);

  if p_vehicle_year is not null then
    v_model_key := public.ohc_remove_normalized_vehicle_token(v_model_key, p_vehicle_year::text);
    v_model_key := public.ohc_remove_normalized_vehicle_token(v_model_key, 'ano');
  end if;

  if public.ohc_normalize_compatibility_text(p_vehicle_generation) <> '' then
    v_model_key := public.ohc_remove_normalized_vehicle_token(v_model_key, p_vehicle_generation);
  end if;

  if public.ohc_normalize_compatibility_text(p_chassis_platform) <> '' then
    v_model_key := public.ohc_remove_normalized_vehicle_token(v_model_key, p_chassis_platform);
  end if;

  -- Variações ortográficas exatas e previsíveis, sem distância de edição.
  v_model_key := replace(v_model_key, 'x drive', 'xdrive');

  if v_brand_key = 'bmw' then
    v_model_key := regexp_replace(v_model_key, '^m ([0-9])', E'm\\1');
    v_model_key := regexp_replace(
      v_model_key,
      '([0-9]{3}) ([ide])($| )',
      E'\\1\\2\\3',
      'g'
    );

    v_without_series := regexp_replace(
      v_model_key,
      '^(serie|series) [0-9]+ (.+)$',
      E'\\2'
    );

    if v_without_series <> '' then
      v_model_key := v_without_series;
    end if;
  end if;

  return public.ohc_normalize_compatibility_text(v_model_key);
end;
$function$

CREATE OR REPLACE FUNCTION public.ohc_build_vehicle_normalized_key(p_vehicle_brand text, p_vehicle_model text, p_vehicle_year integer, p_vehicle_version text DEFAULT NULL::text, p_vehicle_generation text DEFAULT NULL::text, p_chassis_platform text DEFAULT NULL::text, p_motorization text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO ''
AS $function$
  select concat(
    public.ohc_normalize_vehicle_brand(p_vehicle_brand), '|',
    public.ohc_normalize_vehicle_model_v2(
      p_vehicle_brand,
      p_vehicle_model,
      p_vehicle_year,
      p_vehicle_generation,
      p_chassis_platform
    ), '|',
    coalesce(p_vehicle_year::text, ''), '|',
    public.ohc_normalize_compatibility_text(p_vehicle_version), '|',
    public.ohc_normalize_compatibility_text(p_vehicle_generation), '|',
    public.ohc_normalize_compatibility_text(p_chassis_platform), '|',
    public.ohc_normalize_compatibility_text(p_motorization)
  );
$function$

CREATE OR REPLACE FUNCTION public.ohc_record_public_compatibility_query(p_protocol text, p_vehicle_brand text, p_vehicle_model text, p_vehicle_year integer, p_vehicle_version text, p_vehicle_generation text, p_chassis_platform text, p_motorization text, p_question text, p_consent_data_images boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_resolution jsonb;
  v_identification jsonb;
  v_results jsonb := '[]'::jsonb;
  v_recommended_products jsonb := '[]'::jsonb;
  v_recommended_skus text[] := array[]::text[];
  v_status text := 'analise_necessaria';
  v_public_result text := 'Análise necessária';
  v_normalized_key text;
  v_profile_id uuid;
  v_primary_rule_id uuid;
  v_decision_batch_id uuid;
  v_request_id uuid;
  v_photos_expire_at timestamptz;
  v_match_priority integer;
  v_matched boolean := false;
  v_conflict boolean := false;
begin
  if nullif(trim(coalesce(p_protocol, '')), '') is null
     or nullif(trim(coalesce(p_vehicle_brand, '')), '') is null
     or nullif(trim(coalesce(p_vehicle_model, '')), '') is null
     or p_vehicle_year is null
     or p_vehicle_year < 1950
     or p_vehicle_year > 2100
     or not coalesce(p_consent_data_images, false) then
    return jsonb_build_object('ok', false, 'error', 'invalid_public_query');
  end if;

  v_resolution := public.ohc_find_compatibility_memory(
    p_vehicle_brand,
    p_vehicle_model,
    p_vehicle_year,
    nullif(trim(p_vehicle_version), ''),
    nullif(trim(p_vehicle_generation), ''),
    nullif(trim(p_chassis_platform), ''),
    nullif(trim(p_motorization), ''),
    false
  );

  v_results := coalesce(v_resolution -> 'results', '[]'::jsonb);
  v_normalized_key := v_resolution -> 'normalized_input' ->> 'normalized_key';
  v_match_priority := nullif(v_resolution ->> 'match_priority', '')::integer;
  v_matched := coalesce((v_resolution ->> 'matched')::boolean, false);
  v_conflict := coalesce((v_resolution ->> 'conflict')::boolean, false);

  if v_matched then
    if exists (
      select 1 from jsonb_array_elements(v_results) as result(item)
      where item ->> 'status' = 'compativel'
    ) then
      v_status := 'compativel';
      v_public_result := 'Compatível';
    elsif exists (
      select 1 from jsonb_array_elements(v_results) as result(item)
      where item ->> 'status' = 'compativel_com_condicoes'
    ) then
      v_status := 'compativel_com_condicoes';
      v_public_result := 'Compatível com condições';
    elsif exists (
      select 1 from jsonb_array_elements(v_results) as result(item)
      where item ->> 'status' = 'incompativel'
    ) then
      v_status := 'incompativel';
      v_public_result := 'Não compatível';
    end if;
  end if;

  select
    coalesce(jsonb_agg(item order by item ->> 'brand', item ->> 'name', item ->> 'sku'), '[]'::jsonb),
    coalesce(array_agg(item ->> 'sku' order by item ->> 'sku'), array[]::text[])
  into v_recommended_products, v_recommended_skus
  from jsonb_array_elements(v_results) as result(item)
  where item ->> 'status' in ('compativel', 'compativel_com_condicoes');

  if v_matched then
    select
      nullif(item ->> 'rule_id', '')::uuid,
      nullif(item ->> 'decision_batch_id', '')::uuid
    into v_primary_rule_id, v_decision_batch_id
    from jsonb_array_elements(v_results) as result(item)
    order by
      case when item ->> 'status' = v_status then 0 else 1 end,
      coalesce((item ->> 'match_priority')::integer, 99),
      item ->> 'sku'
    limit 1;

    select rule.vehicle_profile_id into v_profile_id
    from public.compatibility_rules as rule
    where rule.id = v_primary_rule_id;
  else
    v_identification := public.ohc_identify_vehicle_profile(
      p_vehicle_brand,
      p_vehicle_model,
      p_vehicle_year,
      nullif(trim(p_vehicle_version), ''),
      nullif(trim(p_vehicle_generation), ''),
      nullif(trim(p_chassis_platform), ''),
      nullif(trim(p_motorization), ''),
      false
    );

    if coalesce((v_identification ->> 'identified')::boolean, false) then
      v_profile_id := nullif(v_identification -> 'profile' ->> 'id', '')::uuid;
    end if;
  end if;

  insert into public.compatibility_requests (
    protocol,
    requested_product_sku,
    requested_product_name,
    recommended_product_skus,
    vehicle_brand,
    vehicle_model,
    vehicle_year,
    vehicle_version,
    vehicle_generation,
    vehicle_chassis_platform,
    vehicle_motorization,
    generation_chassis,
    current_steering_notes,
    customer_name,
    whatsapp,
    email,
    consent_data_images,
    status,
    vehicle_profile_id,
    vehicle_normalized_key,
    matched_rule_id,
    decision_batch_id,
    decision_source,
    conflict_detected,
    result_presented
  ) values (
    trim(p_protocol),
    null,
    null,
    v_recommended_skus,
    trim(p_vehicle_brand),
    trim(p_vehicle_model),
    p_vehicle_year,
    nullif(trim(p_vehicle_version), ''),
    nullif(trim(p_vehicle_generation), ''),
    nullif(trim(p_chassis_platform), ''),
    nullif(trim(p_motorization), ''),
    coalesce(nullif(trim(p_chassis_platform), ''), nullif(trim(p_vehicle_generation), '')),
    nullif(trim(p_question), ''),
    null,
    null,
    null,
    true,
    v_status,
    v_profile_id,
    v_normalized_key,
    v_primary_rule_id,
    v_decision_batch_id,
    case
      when v_matched then 'learned_rule'
      when v_conflict then 'conflict'
      else 'manual_review'
    end,
    v_conflict,
    jsonb_build_object(
      'status', v_status,
      'public_result', v_public_result,
      'matched_by_rule', v_matched,
      'conflict_detected', v_conflict,
      'match_priority', v_match_priority,
      'normalized_input', coalesce(v_resolution -> 'normalized_input', '{}'::jsonb),
      'recommended_products', v_recommended_products,
      'evaluated_results', v_results,
      'matched_rule_id', v_primary_rule_id,
      'decision_batch_id', v_decision_batch_id
    )
  )
  returning id, photos_expire_at into v_request_id, v_photos_expire_at;

  return jsonb_build_object(
    'ok', true,
    'request_id', v_request_id,
    'protocol', trim(p_protocol),
    'status', v_status,
    'public_result', v_public_result,
    'matched_by_rule', v_matched,
    'conflict_detected', v_conflict,
    'match_priority', v_match_priority,
    'recommended_products', v_recommended_products,
    'evaluated_results', v_results,
    'photos_expire_at', v_photos_expire_at
  );
exception
  when unique_violation then
    return jsonb_build_object('ok', false, 'error', 'protocol_collision');
end;
$function$

CREATE OR REPLACE FUNCTION public.ohc_consume_public_rate_limit()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_now timestamptz := clock_timestamp();
  v_window_started_at timestamptz;
  v_request_count integer;
  v_limit constant integer := 60;
  v_window_seconds constant integer := 60;
  v_retry_after integer;
begin
  insert into public.compatibility_public_rate_limits (
    scope,
    window_started_at,
    request_count,
    updated_at
  ) values (
    'public-submit-global',
    v_now,
    1,
    v_now
  )
  on conflict (scope) do update set
    window_started_at = case
      when public.compatibility_public_rate_limits.window_started_at <= v_now - make_interval(secs => v_window_seconds)
        then v_now
      else public.compatibility_public_rate_limits.window_started_at
    end,
    request_count = case
      when public.compatibility_public_rate_limits.window_started_at <= v_now - make_interval(secs => v_window_seconds)
        then 1
      else public.compatibility_public_rate_limits.request_count + 1
    end,
    updated_at = v_now
  returning window_started_at, request_count
    into v_window_started_at, v_request_count;

  v_retry_after := greatest(
    1,
    ceil(v_window_seconds - extract(epoch from (v_now - v_window_started_at)))::integer
  );

  return jsonb_build_object(
    'allowed', v_request_count <= v_limit,
    'limit', v_limit,
    'remaining', greatest(v_limit - v_request_count, 0),
    'retry_after', case when v_request_count <= v_limit then 0 else v_retry_after end
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.ohc_attach_bmw_compatibility_suggestions()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if coalesce(btrim(new.admin_notes), '') = '' then
    new.admin_notes := public.ohc_bmw_compatibility_suggestions(
      new.vehicle_brand,
      new.vehicle_model,
      new.generation_chassis
    );
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.ohc_resolve_compatibility(p_product_sku text, p_vehicle_brand text, p_vehicle_model text, p_vehicle_year integer, p_generation_chassis text, p_vehicle_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_product_key text := public.ohc_normalize_compatibility_text(p_product_sku);
  v_brand_key text := public.ohc_normalize_compatibility_text(p_vehicle_brand);
  v_model_key text := public.ohc_normalize_compatibility_text(p_vehicle_model);
  v_generation_key text := public.ohc_normalize_compatibility_text(p_generation_chassis);
  v_version_key text := public.ohc_normalize_compatibility_text(p_vehicle_version);
  v_candidate_count bigint := 0;
  v_status_count bigint := 0;
  v_rule_id uuid;
  v_status text;
begin
  if v_product_key = '' or v_brand_key = '' or v_model_key = '' or
     p_vehicle_year is null or p_vehicle_year < 1950 or p_vehicle_year > 2100 then
    return jsonb_build_object(
      'matched', false,
      'conflict', false,
      'reason', 'invalid_input'
    );
  end if;

  with candidates as (
    select
      rule.id,
      rule.status,
      rule.updated_at,
      (case
        when rule.generation_key = v_generation_key and v_generation_key <> '' then 4
        when rule.generation_key = '' then 1
        else 0
      end) +
      (case
        when rule.version_key = v_version_key and v_version_key <> '' then 2
        when rule.version_key = '' then 1
        else 0
      end) as specificity
    from public.compatibility_rules as rule
    where rule.active
      and rule.product_sku_key = v_product_key
      and rule.vehicle_brand_key = v_brand_key
      and rule.vehicle_model_key = v_model_key
      and p_vehicle_year between rule.year_from and rule.year_to
      and (rule.generation_key = '' or rule.generation_key = v_generation_key)
      and (rule.version_key = '' or rule.version_key = v_version_key)
  ), best as (
    select *
    from candidates
    where specificity = (select max(specificity) from candidates)
  )
  select
    count(*),
    count(distinct status),
    (array_agg(id order by updated_at desc))[1],
    (array_agg(status order by updated_at desc))[1]
  into v_candidate_count, v_status_count, v_rule_id, v_status
  from best;

  if v_candidate_count = 0 then
    return jsonb_build_object(
      'matched', false,
      'conflict', false,
      'reason', 'no_rule'
    );
  end if;

  if v_status_count > 1 then
    return jsonb_build_object(
      'matched', false,
      'conflict', true,
      'reason', 'conflicting_rules',
      'candidate_count', v_candidate_count
    );
  end if;

  return jsonb_build_object(
    'matched', true,
    'conflict', false,
    'rule_id', v_rule_id,
    'status', v_status,
    'candidate_count', v_candidate_count
  );
end;
